# HEADER
# =========================================================

st.title("👕 Fashion MNIST Image Classifier")

st.write(
    "Fully Connected Neural Network (FCNN) trained on the "
    "Fashion MNIST dataset."
)

st.info(
    "For the most reliable demonstration, use the built-in "
    "Fashion MNIST samples below. You can also upload your own "
    "PNG/JPG clothing image."
)


# =========================================================
# LOAD MODEL
# =========================================================

try:
    model, class_names = load_model()
except Exception as error:
    st.error(f"Unable to load model.pkl: {error}")
    st.stop()


# =========================================================
# SIDEBAR
# =========================================================

with st.sidebar:

    st.header("📌 Model Information")

    st.write("**Model:** Fully Connected Neural Network")
    st.write("**Dataset:** Fashion MNIST")
    st.write("**Input:** 28 × 28 grayscale")
    st.write("**Output:** 10 classes")
    st.write("**Normalization:** pixel / 255.0")

    st.markdown("---")

    match_fashion_mnist = st.checkbox(
        "Match Fashion MNIST preprocessing",
        value=True
    )

    st.markdown("---")

    st.subheader("Fashion MNIST Classes")

    for index, class_name in enumerate(class_names):
        st.write(f"{index} — {class_name}")


# =========================================================
# BUILT-IN SAMPLE TESTING
# =========================================================

st.subheader("🧪 Test With Built-In Fashion-MNIST Samples")

st.write(
    "These samples are embedded inside app.py, so a recruiter "
    "does not need to find or download separate image files."
)

sample_name = st.selectbox(
    "Choose a sample image",
    list(BUILT_IN_SAMPLES.keys())
)

selected_sample = decode_sample(
    BUILT_IN_SAMPLES[sample_name]
)

sample_column, sample_info_column = st.columns([1, 2])

with sample_column:

    st.image(
        selected_sample,
        caption=f"Built-in sample: {sample_name}",
        width=280
    )

with sample_info_column:

    st.write("### Quick Model Test")

    if st.button(
        "🔍 Predict Selected Sample",
        type="primary"
    ):

        try:

            _, processed_image, model_input = prepare_image(
                selected_sample,
                match_fashion_mnist
            )

            probabilities = np.asarray(
                model.predict(
                    model_input,
                    verbose=0
                )
            )[0]

            predicted_index = int(
                np.argmax(probabilities)
            )

            predicted_class = class_names[
                predicted_index
            ]

            confidence = float(
                probabilities[predicted_index]
            )

            st.success(
                f"Prediction: **{predicted_class}**"
            )

            st.metric(
                "Confidence",
                f"{confidence * 100:.2f}%"
            )

            st.caption(
                "The selected sample is a real Fashion-MNIST "
                "image displayed in the original notebook."
            )

        except Exception as error:
            st.error(
                f"Prediction failed: {error}"
            )


# =========================================================
# USER IMAGE UPLOAD
# =========================================================

st.markdown("---")

st.subheader("📤 Upload Your Own Clothing Image")

uploaded_file = st.file_uploader(
    "Choose a PNG, JPG, or JPEG image",
    type=["png", "jpg", "jpeg"]
)

if uploaded_file is not None:

    try:

        original_image, processed_image, model_input = prepare_image(
            uploaded_file,
            match_fashion_mnist
        )

        first_column, second_column = st.columns(2)

        with first_column:

            st.subheader("Original Image")

            st.image(
                original_image,
                use_container_width=True
            )

        with second_column:

            st.subheader("Model Input")

            st.image(
                processed_image,
                caption="28×28 image sent to the FCNN",
                width=280
            )

    except Exception as error:

        st.error(
            f"Image preprocessing failed: {error}"
        )

        st.stop()

    if st.button(
        "🔍 Predict Uploaded Image",
        type="primary"
    ):

        try:

            probabilities = np.asarray(
                model.predict(
                    model_input,
                    verbose=0
                )
            )[0]

            if len(probabilities) != len(class_names):

                st.error(
                    "Unexpected model output. "
                    "Please verify model.pkl."
                )

                st.stop()

            predicted_index = int(
                np.argmax(probabilities)
            )

            predicted_class = class_names[
                predicted_index
            ]

            confidence = float(
                probabilities[predicted_index]
            )

            st.success(
                f"Predicted Category: **{predicted_class}**"
            )

            st.metric(
                "Prediction Confidence",
                f"{confidence * 100:.2f}%"
            )

            st.subheader("Top 3 Predictions")

            top_indices = np.argsort(
                probabilities
            )[::-1][:3]

            for rank, index in enumerate(
                top_indices,
                start=1
            ):

                st.write(
                    f"**{rank}. {class_names[index]}** — "
                    f"{probabilities[index] * 100:.2f}%"
                )

            st.subheader("Class Probabilities")

            probability_data = {
                class_names[index]:
                    float(probabilities[index])
                for index in range(len(class_names))
            }

            st.bar_chart(
                probability_data
            )

        except Exception as error:

            st.error(
                f"Prediction failed: {error}"
            )


# =========================================================
# EXPLANATION
# =========================================================

with st.expander("📖 How this app works"):

    st.markdown(
        """
### Model

The app loads the trained Fashion MNIST FCNN from `model.pkl`.

### Input processing

The image is:

1. Converted to grayscale.
2. Converted toward the dark-background Fashion MNIST format.
3. Cropped around the main object when possible.
4. Resized to 28 × 28 pixels.
5. Normalized from 0–255 to 0–1.
6. Sent to the trained FCNN.

### Recruiter testing

The app contains real Fashion-MNIST sample images directly inside
`app.py`. Therefore the recruiter can test the trained model
immediately without finding any local dataset files.

The app also accepts normal PNG/JPG/JPEG clothing images, but those
can be less reliable because the model was trained specifically on
Fashion-MNIST-style images.
"""
    )

st.caption(
    "Fashion MNIST FCNN Deployment — Streamlit"
)
